// ---- events (events.v1.schema.json) ----
export const DOCS_EVENT_TYPES = ["engine.health_changed","drive.created","drive.updated","drive.deleted","drive.sync_started","drive.sync_completed","drive.sync_failed","drive.sync_held","file.state_changed","file.renamed","file.removed","files.bulk_changed","review.changed","review.decided","ontology.version_published","share.created","share.state_changed","share.mount_removed","pack.compiled","pack.leak_blocked","usage.changed","refs.accessed","drive.freshness_changed","share.update_appended","ontology.constraint_violated","file.progress","stream.lagging"] as const;
export type DocsEventType = (typeof DOCS_EVENT_TYPES)[number];
export const DOCS_PERSISTENT_EVENT_TYPES = ["engine.health_changed","drive.created","drive.updated","drive.deleted","drive.sync_started","drive.sync_completed","drive.sync_failed","drive.sync_held","file.state_changed","file.renamed","file.removed","files.bulk_changed","review.changed","review.decided","ontology.version_published","share.created","share.state_changed","share.mount_removed","pack.compiled","pack.leak_blocked","usage.changed","refs.accessed","drive.freshness_changed","share.update_appended","ontology.constraint_violated"] as const;
export const DOCS_TRANSIENT_EVENT_TYPES = ["file.progress","stream.lagging"] as const;
export function isDocsEventType(value: unknown): value is DocsEventType {
  return (DOCS_EVENT_TYPES as readonly unknown[]).includes(value);
}
export function isPersistentDocsEvent(type: string): boolean {
  return (DOCS_PERSISTENT_EVENT_TYPES as readonly string[]).includes(type);
}

